--
-- Table structure for table `rencontre`
--

DROP TABLE IF EXISTS `rencontre`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rencontre` (
  `Id_Rencontre` int(11) NOT NULL AUTO_INCREMENT,
  `Date` date NOT NULL,
  `Heure` time NOT NULL,
  `Id_Division` int(11) DEFAULT NULL,
  `Division` varchar(5) NOT NULL,
  `Poule` tinyint(11) NOT NULL,
  `Id_EquipeDom` int(11) NOT NULL,
  `Id_EquipeExt` int(11) DEFAULT NULL,
  `Phase` tinyint(1) NOT NULL,
  `Journee` tinyint(4) DEFAULT NULL,
  `id_Salle` int(11) DEFAULT NULL,
  `ArbitrageObligatoire` tinyint(1) NOT NULL DEFAULT 1,
  `Commentaire` text DEFAULT NULL,
  PRIMARY KEY (`Id_Rencontre`),
  KEY `fk_rencontre_division` (`Id_Division`),
  KEY `fk_rencontre_salle` (`id_Salle`),
  KEY `fk_rencontre_equipe_dom` (`Id_EquipeDom`),
  KEY `fk_rencontre_equipe_ext` (`Id_EquipeExt`),
  KEY `idx_rencontre_date` (`Date`),
  KEY `Division` (`Division`),
  CONSTRAINT `fk_rencontre_division` FOREIGN KEY (`Id_Division`) REFERENCES `division` (`Id_Division`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_equipe_dom` FOREIGN KEY (`Id_EquipeDom`) REFERENCES `equipe` (`Id_Equipe`) ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_equipe_ext` FOREIGN KEY (`Id_EquipeExt`) REFERENCES `equipe` (`Id_Equipe`) ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_salle` FOREIGN KEY (`id_Salle`) REFERENCES `salle` (`Id_Salle`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Les différantes rencontre de la phase toutes divisions confondu.';
/*!40101 SET character_set_client = @saved_cs_client */;

